// Generated by OSL (@osl/backend-hono-trpc-vite). Files: begin an upload, receive or redirect to its bytes, read its metadata, and check file fields on writes.
// Do not edit: this file is rewritten on every osl generate.

import { randomUUID } from "node:crypto";
import type { Readable } from "node:stream";
import { eq } from "drizzle-orm";
import { db } from "./db/client";
import { oslFiles as filesTable, type FileRef, type OslFile } from "./db/schema";
import { fail } from "./server/errors";
import type { Session } from "./server/auth";
import * as storage from "./storage";

export type { FileRef };

/** How a file appears in API responses */
export type PublicFile = { id: string; name: string; size: number; type: string; url: string };
export type FileRecord = PublicFile & { status: "pending" | "ready" };

/** The largest upload begin accepts, in bytes (OSL_MAX_UPLOAD_BYTES, default 50 MB); fields may lower it */
export const MAX_UPLOAD_BYTES = Number(process.env.OSL_MAX_UPLOAD_BYTES ?? 50 * 1024 * 1024);

/** Every file is served through the API, which streams local files and redirects to signed S3 URLs */
export function fileUrl(id: string): string {
  return "/api/files/" + id + "/content";
}

export function presentFileRef(ref: FileRef | null | undefined): PublicFile | null {
  if (!ref) return null;
  return { id: ref.id, name: ref.name, size: ref.size, type: ref.type, url: fileUrl(ref.id) };
}

function present(row: OslFile): FileRecord {
  return { id: row.id, name: row.name, size: row.size, type: row.type, url: fileUrl(row.id), status: row.status };
}

export interface BeginUploadInput {
  name: string;
  type: string;
  size: number;
}

/** Create the file record and say where the bytes go. The record stays pending until the bytes are in place. */
export async function beginUpload(input: BeginUploadInput, session: Session | null): Promise<{ file: FileRecord; upload: storage.UploadTarget }> {
  if (input.size > MAX_UPLOAD_BYTES) fail(400, "validation", "Files may be at most " + MAX_UPLOAD_BYTES + " bytes");
  const id = randomUUID();
  const key = "files/" + id;
  const [row] = await db
    .insert(filesTable)
    .values({ id, key, name: input.name, size: input.size, type: input.type, status: "pending", owner_id: session?.user.id ?? null })
    .returning();
  const upload = await storage.uploadTarget(key, input.type, fileUrl(id));
  return { file: present(row), upload };
}

async function fileRow(id: string): Promise<OslFile> {
  const row = await db.query.oslFiles.findFirst({ where: eq(filesTable.id, id) }).catch(() => undefined);
  if (!row) fail(404, "not_found", "Not found");
  return row;
}

/** Mark an upload finished once its bytes are in storage; the stored size wins over the declared one. */
export async function completeUpload(id: string): Promise<FileRecord> {
  const row = await fileRow(id);
  if (row.status === "ready") return present(row);
  const size = await storage.objectSize(row.key);
  if (size === null) fail(400, "upload_incomplete", "The file's bytes have not been uploaded yet");
  const [updated] = await db.update(filesTable).set({ status: "ready", size }).where(eq(filesTable.id, id)).returning();
  return present(updated);
}

export async function getFile(id: string): Promise<FileRecord> {
  return present(await fileRow(id));
}

/** Local storage only: receive the bytes the client PUTs to the API and mark the file ready. */
export async function receiveContent(id: string, body: ReadableStream<Uint8Array> | Uint8Array | null): Promise<FileRecord> {
  if (storage.storageKind() !== "local") fail(400, "not_local", "Upload to the URL from POST /api/files instead");
  const row = await fileRow(id);
  const size = await storage.putLocal(row.key, body);
  const [updated] = await db.update(filesTable).set({ status: "ready", size }).where(eq(filesTable.id, id)).returning();
  return present(updated);
}

export type FileContent =
  | { kind: "redirect"; url: string }
  | { kind: "stream"; stream: Readable; type: string; size: number; disposition: string };

/** The bytes of a ready file: a stream from local storage, or a redirect to a signed S3 URL. */
export async function fileContent(id: string): Promise<FileContent> {
  const row = await fileRow(id);
  if (row.status !== "ready") fail(404, "not_found", "Not found");
  if (storage.storageKind() === "local") {
    return {
      kind: "stream",
      stream: storage.readLocal(row.key),
      type: row.type,
      size: row.size,
      disposition: storage.contentDisposition(row.name, row.type)
    };
  }
  return { kind: "redirect", url: await storage.downloadUrl(row.key, row.name, row.type) };
}

export interface FileFieldSpec<K extends string = string> {
  column: K;
  accept?: readonly string[];
  maxSize?: number;
}

function typeMatches(pattern: string, type: string): boolean {
  if (pattern.endsWith("/*")) return type.toLowerCase().startsWith(pattern.slice(0, -1).toLowerCase());
  return pattern.toLowerCase() === type.toLowerCase();
}

/** Replace the file ids in a write body with the files' snapshots, checking each is ready and allowed by its field. */
/** The input with its file ids replaced by references; a required id becomes a required FileRef */
export type WithFileRefs<T, K extends string> = Omit<T, K> & { [P in K & keyof T]: FileRef | Exclude<T[P], string> };

export async function resolveFileRefs<T extends object, K extends string>(
  values: T,
  specs: readonly FileFieldSpec<K>[]
): Promise<WithFileRefs<T, K>> {
  const out = { ...values } as Record<string, unknown>;
  for (const spec of specs) {
    const raw = out[spec.column];
    if (raw === undefined || raw === null || typeof raw === "object") continue;
    const row = await db.query.oslFiles.findFirst({ where: eq(filesTable.id, String(raw)) }).catch(() => undefined);
    if (!row || row.status !== "ready") fail(400, "validation", spec.column + ": no uploaded file with id " + String(raw));
    if (spec.accept && !spec.accept.some(pattern => typeMatches(pattern, row.type)))
      fail(400, "validation", spec.column + ": " + row.type + " is not an accepted type (" + spec.accept.join(", ") + ")");
    if (spec.maxSize && row.size > spec.maxSize)
      fail(400, "validation", spec.column + ": the file is larger than " + spec.maxSize + " bytes");
    const ref: FileRef = { id: row.id, key: row.key, name: row.name, size: row.size, type: row.type };
    out[spec.column] = ref;
  }
  return out as WithFileRefs<T, K>;
}
